pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address depositor, address other, uint256 amount, uint256 newRate) public {
        vm.assume(depositor != address(0) && other != depositor && other != c.owner());
        amount = bound(amount, 1, type(uint128).max);
        newRate = bound(newRate, 0, type(uint128).max);

        // depositor deposits
        vm.deal(depositor, amount);
        vm.prank(depositor);
        c.deposit{value: amount}();

        // other changes rewardRate (this succeeds only in the mutant)
        vm.prank(other);
        c.setRewardRate(newRate);

        // depositor claims
        vm.prank(depositor);
        c.claim();

        // The reward credited to depositor must equal amount * initial rewardRate (100)
        // The bug allows the reward to diverge because other can raise rewardRate before claim
        uint256 expected = amount * 100;
        uint256 actual = c.reward(depositor);
        assertTrue(actual == expected);
    }
}

