pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, address user) public {
        vm.assume(user != address(0));
        vm.assume(amount1 > 0 && amount2 > 0);
        vm.assume(amount1 + amount2 > amount1); // no overflow

        // First deposit
        vm.deal(user, amount1);
        vm.prank(user);
        c.deposit{value: amount1}();

        // Second deposit
        vm.deal(user, amount2);
        vm.prank(user);
        c.deposit{value: amount2}();

        // Trigger claim (drives the difference, but the property is about balances)
        vm.prank(user);
        c.claim();

        // General rule: the recorded balance for the user equals the total Ether they sent
        uint256 totalSent = amount1 + amount2;
        uint256 recordedBalance = c.balance(user);
        assertTrue(recordedBalance == totalSent);
    }
}

