pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 deposit0, uint256 deposit1, address user) public {
        // Keep amounts reasonable to avoid overflow; still wide enough to find the bug.
        deposit0 = bound(deposit0, 1, 1e24);
        deposit1 = bound(deposit1, 1, 1e24);
        vm.assume(user != address(0) && user != address(this) && user != address(c));

        // First deposit by user
        vm.deal(user, deposit0);
        vm.prank(user);
        c.deposit{value: deposit0}();

        // Claim once after first deposit to set reward[user] to a known baseline
        vm.prank(user);
        c.claim();

        uint256 rewardAfterFirstClaim = c.reward(user);

        // Second deposit by the SAME user (the bug overwrites balance)
        vm.deal(user, deposit1);
        vm.prank(user);
        c.deposit{value: deposit1}();

        // Claim again
        vm.prank(user);
        c.claim();

        uint256 rewardAfterSecondClaim = c.reward(user);

        // In the reference contract, the total reward after two claims must be:
        // rewardAfterFirstClaim + (balance[user] * rateSnapshot[user] at moment of second claim).
        // Since rewardRate has not changed (100) and rateSnapshot is updated on each deposit,
        // balance[user] after second deposit is deposit0 + deposit1 in reference, but only deposit1 in buggy.
        // Thus for the reference, rewardAfterSecondClaim == rewardAfterFirstClaim + (deposit0+deposit1)*100,
        // while the buggy version gives rewardAfterSecondClaim == rewardAfterFirstClaim + deposit1*100.
        // We assert the reference behaviour; the buggy version will fail this equality.
        uint256 balanceAfterSecondDeposit = c.balance(user);
        uint256 rateAfterSecondDeposit = c.rateSnapshot(user);
        uint256 expectedReward = rewardAfterFirstClaim + balanceAfterSecondDeposit * rateAfterSecondDeposit;

        assertTrue(rewardAfterSecondClaim == expectedReward);
    }
}

