pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 first, uint256 second, uint256 rate1, uint256 rate2, address user) public {
        vm.assume(user != address(0) && user != address(this) && user != address(c));
        first = bound(first, 1, 1000 ether);
        second = bound(second, 1, 1000 ether);
        vm.assume(rate1 <= type(uint256).max / first);
        vm.assume(rate2 <= type(uint256).max / second);

        vm.prank(address(c.owner()));
        c.setRewardRate(rate1);

        vm.deal(user, first);
        vm.prank(user);
        c.deposit{value: first}();

        uint256 expectedReward1 = first * rate1;

        vm.prank(address(c.owner()));
        c.setRewardRate(rate2);

        vm.deal(user, second);
        vm.prank(user);
        c.deposit{value: second}();

        uint256 expectedReward2 = second * rate2;

        uint256 rewardBefore = c.reward(user);
        vm.prank(user);
        c.claim();
        uint256 rewardAfter = c.reward(user);
        uint256 actualReward = rewardAfter - rewardBefore;

        assertTrue(actualReward == expectedReward1 + expectedReward2);
    }
}

