import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 a1, uint256 a2, uint256 r1, uint256 r2, address user) public {
        vm.assume(a1 > 0 && a2 > 0);
        vm.assume(user != address(0) && user != address(this));
        vm.deal(user, a1 + a2);

        // first deposit
        vm.prank(c.owner());
        c.setRewardRate(r1);
        vm.prank(user);
        c.deposit{value: a1}();

        uint256 snapshotBalance1 = c.balance(user);
        uint256 snapshotReward1 = c.reward(user);

        // second deposit
        vm.prank(c.owner());
        c.setRewardRate(r2);
        vm.prank(user);
        c.deposit{value: a2}();

        // claim
        vm.prank(user);
        c.claim();

        uint256 finalBalance = c.balance(user);
        uint256 finalReward = c.reward(user);

        // Rule: reward gained + final balance == initial balance (a1)
        // In reference: balance is a1+a2, reward = a1*r1 + a2*r2 => sum = a1+a2 + a1*r1 + a2*r2 (not equal to a1)
        // Wait, the bug overwrites balance on second deposit to a2, losing a1.
        // Let's target a property that holds in reference but fails in bug.
        // Reference: finalBalance == a1 + a2. Bug: finalBalance == a2.
        // However, the rule must be general and involve claim.
        // The reward should reflect the balance at the time of deposit.
        // In reference: reward gained from first deposit is a1 * r1; from second deposit is a2 * r2.
        // After claim, finalReward = snapshotReward1 + a1*r1 + a2*r2.
        // In bug: reward gained from first deposit is 0 (balance was overwritten to a2, so claim after second deposit sees balance = a2 and rateSnapshot = r2, so reward = a2*r2). Wait, the user calls claim after the second deposit. In bug, before claim, balance = a2, rateSnapshot = r2. So reward = a2*r2. The first deposit's a1 is completely lost from both balance and reward.
        // So a property: after the second deposit and before claim, balance(user) must be a1 + a2. That does not involve claim.
        // We need to involve claim.
        // Property: after claim, finalReward must be at least a1 * r1. In bug, finalReward might be a2*r2 and could be less if a1 is huge and r1 is large.
        // But we need a property that ALWAYS holds in reference. In reference, finalReward = previousReward + a1*r1 + a2*r2. Since a1>0, r1>=0, finalReward >= a1*r1 always. In bug, finalReward = previousReward + a2*r2, which could be smaller than a1*r1. So assertTrue(finalReward >= a1 * r1) holds in reference but can fail in bug.
        // However, we need to handle overflow? Solidity 0.8.0 has overflow checks, but a1*r1 could overflow and revert. The fuzzer might hit overflow and revert, causing assertion not reached. We need to bound a1 and r1 to prevent overflow, or wrap in try/catch. Let's bound a1 and r1 to avoid overflow: a1 <= type(uint256).max / 2, r1 <= type(uint256).max / 2. But we already have a1 and a2 > 0, we can bound them.

        bound(a1, 1, type(uint256).max / 2);
        bound(a2, 1, type(uint256).max / 2);
        bound(r1, 0, type(uint256).max / 2);
        bound(r2, 0, type(uint256).max / 2);

        // Re-do the setup with bounds to ensure overflow doesn't occur
        // Actually we already did vm.assume and deals. We should bound first.
        // So we need to restructure: bound at the top, then vm.assume.
        // I'll rewrite cleanly.
    }
}

