pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 deposit1, uint256 deposit2, uint256 deposit3) public {
        // Bound deposits to avoid overflow and keep them positive
        deposit1 = bound(deposit1, 1, 1e18);
        deposit2 = bound(deposit2, 1, 1e18);
        deposit3 = bound(deposit3, 1, 1e18);

        // Deploy a helper that reverts on receiving Ether to act as adversarial counterparty
        Reverter reverter = new Reverter();
        address alice = address(0x1000);
        address bob = address(reverter);

        // Alice deposits twice
        vm.deal(alice, deposit1 + deposit2);
        vm.prank(alice);
        c.deposit{value: deposit1}();
        vm.prank(alice);
        c.deposit{value: deposit2}();

        // Bob (the reverter contract) deposits once
        vm.deal(bob, deposit3);
        vm.prank(bob);
        c.deposit{value: deposit3}();

        // Alice withdraws first, which should succeed (EOA always receives)
        vm.prank(alice);
        c.withdraw();

        // Bob attempts to withdraw; this low-level call to the reverter will fail
        vm.prank(bob);
        try c.withdraw() { } catch { }

        // After these operations, the sum of Alice's and Bob's balances must equal Bob's deposit,
        // because Alice's balance should be zero after her successful withdrawal and Bob's should
        // remain untouched (his withdrawal failed). The bug causes Alice's second deposit to overwrite
        // her first, making her balance smaller, so the sum will differ from deposit3.
        uint256 sumBalances = c.balance(alice) + c.balance(bob);
        assertTrue(sumBalances == deposit3);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

