        // actor1 deposits
        vm.deal(actor1, depositAmount1);
        vm.prank(actor1);
        c.deposit{value: depositAmount1}();

        // owner changes reward rate
        vm.prank(c.owner());
        c.setRewardRate(newRate);

        // actor2 deposits
        vm.deal(actor2, depositAmount2);
        vm.prank(actor2);
        c.deposit{value: depositAmount2}();

        // actor2 claims
        vm.prank(actor2);
        c.claim();

        uint256 snapshot2 = c.rateSnapshot(actor2);
        uint256 currentRate2 = c.rewardRate();
        assertTrue(snapshot2 == newRate || snapshot2 == currentRate2);
    }
}

