    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 newRate, address caller, address changer) public {
        // Keep parameters in an admissible domain: depositAmount > 0 to ensure balance is non-zero,
        // and caller != changer to test non-owner rate change in the buggy version.
