        // Let a different account (changer) attempt to change the reward rate.
        vm.prank(changer);
        c.setRewardRate(newRate);

        // Calculate expected reward based on the snapshot rate that was stored at deposit time.
        uint256 balanceCaller = c.balance(caller);
        uint256 expectedReward = balanceCaller * snapRate;

        // Call claim() and record the returned reward amount.
        vm.prank(caller);
